-- AI Dental Hospital OS Enterprise CRM & Operations migration
-- Safe to run on an existing v2 database. Startup also applies these tables automatically.
CREATE TABLE IF NOT EXISTS patient_status_history (id SERIAL PRIMARY KEY,patient_id INT REFERENCES patients(id) ON DELETE CASCADE,status VARCHAR(80) NOT NULL,notes TEXT,changed_by INT REFERENCES users(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS enquiries (id SERIAL PRIMARY KEY,patient_id INT REFERENCES patients(id) ON DELETE SET NULL,name VARCHAR(160) NOT NULL,phone VARCHAR(40),email VARCHAR(180),source VARCHAR(80),interest VARCHAR(160),stage VARCHAR(60) DEFAULT 'NEW',assigned_to INT REFERENCES users(id),next_followup TIMESTAMP,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS leads (id SERIAL PRIMARY KEY,enquiry_id INT REFERENCES enquiries(id) ON DELETE SET NULL,name VARCHAR(160) NOT NULL,phone VARCHAR(40),source VARCHAR(80),stage VARCHAR(60) DEFAULT 'NEW',assigned_to INT REFERENCES users(id),expected_value NUMERIC(12,2) DEFAULT 0,next_followup TIMESTAMP,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS doctors (id SERIAL PRIMARY KEY,user_id INT UNIQUE REFERENCES users(id) ON DELETE CASCADE,specialization VARCHAR(160),registration_no VARCHAR(100),phone VARCHAR(40),chair VARCHAR(60),active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS suppliers (id SERIAL PRIMARY KEY,name VARCHAR(200) NOT NULL,contact_person VARCHAR(160),phone VARCHAR(40),email VARCHAR(180),gstin VARCHAR(40),address TEXT,active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS partners (id SERIAL PRIMARY KEY,name VARCHAR(200) NOT NULL,type VARCHAR(100),contact_person VARCHAR(160),phone VARCHAR(40),email VARCHAR(180),commission_percent NUMERIC(5,2) DEFAULT 0,active BOOLEAN DEFAULT TRUE,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS followups (id SERIAL PRIMARY KEY,patient_id INT REFERENCES patients(id) ON DELETE CASCADE,assigned_to INT REFERENCES users(id),type VARCHAR(80),due_at TIMESTAMP NOT NULL,status VARCHAR(50) DEFAULT 'PENDING',notes TEXT,completed_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS recalls (id SERIAL PRIMARY KEY,patient_id INT REFERENCES patients(id) ON DELETE CASCADE,type VARCHAR(100) NOT NULL,due_at DATE NOT NULL,status VARCHAR(50) DEFAULT 'DUE',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,completed_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS complaints (id SERIAL PRIMARY KEY,patient_id INT REFERENCES patients(id) ON DELETE SET NULL,category VARCHAR(100),description TEXT NOT NULL,severity VARCHAR(40) DEFAULT 'MEDIUM',status VARCHAR(50) DEFAULT 'OPEN',assigned_to INT REFERENCES users(id),resolution TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,closed_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS escalations (id SERIAL PRIMARY KEY,complaint_id INT REFERENCES complaints(id) ON DELETE CASCADE,level INT DEFAULT 1,assigned_to INT REFERENCES users(id),reason TEXT,status VARCHAR(50) DEFAULT 'OPEN',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,resolved_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS document_checklists (id SERIAL PRIMARY KEY,patient_id INT REFERENCES patients(id) ON DELETE CASCADE,document_type VARCHAR(120) NOT NULL,required BOOLEAN DEFAULT TRUE,status VARCHAR(40) DEFAULT 'PENDING',document_id INT REFERENCES patient_documents(id) ON DELETE SET NULL,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
